"""Finding free time between busy meetings. Times are minutes after midnight."""

from __future__ import annotations

from planner.clock import parse_hhmm

DAY_START = "09:00"
DAY_END = "17:00"

Interval = tuple[int, int]


def merge_busy(busy: list[Interval]) -> list[Interval]:
    """Sort busy intervals and merge the ones that overlap or touch."""
    merged: list[Interval] = []
    for start, end in sorted(busy):
        if merged and start <= merged[-1][1]:
            merged[-1] = (merged[-1][0], max(merged[-1][1], end))
        else:
            merged.append((start, end))
    return merged


def busy_minutes(busy: list[Interval]) -> int:
    """Total busy time in minutes, counting overlaps once."""
    return sum(end - start for start, end in merge_busy(busy))


def free_slots(
    busy: list[Interval], day_start: str = DAY_START, day_end: str = DAY_END
) -> list[Interval]:
    """Free intervals between day_start and day_end."""
    free: list[Interval] = []
    cursor = parse_hhmm(day_start)
    for start, end in merge_busy(busy):
        if start > cursor:
            free.append((cursor, start))
        cursor = max(cursor, end)
    if cursor < parse_hhmm(day_end):
        free.append((cursor, parse_hhmm(day_end)))
    return free


def first_fit(
    busy: list[Interval], length: int, day_start: str = DAY_START, day_end: str = DAY_END
) -> int | None:
    """Start of the earliest free slot of at least length minutes, or None."""
    for start, end in free_slots(busy, day_start, day_end):
        if end - start >= length:
            return start
    return None

